{"implementation": "def solve(case):
    """Filter Toolformer-style API call candidates by normalized loss gain."""
    import math

    def fail(message):
        raise ValueError(message)

    def is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    payload = case.get("payload", case) if isinstance(case, dict) else fail("case must be a mapping")
    if not isinstance(payload, dict):
        fail("payload must be a mapping")

    if "threshold" not in payload:
        fail("missing threshold")
    threshold = payload["threshold"]
    if not is_number(threshold):
        fail("threshold must be a finite number")

    if "calls" not in payload:
        fail("missing calls")
    calls = payload["calls"]
    if not isinstance(calls, list):
        fail("calls must be a list")

    diagnostics = []
    accepted_call_ids = []

    seen_ids = set()
    required = ("call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable")

    for source_index, call in enumerate(calls):
        if not isinstance(call, dict):
            fail("each call must be a mapping")
        for field in required:
            if field not in call:
                fail("missing call field: " + field)

        call_id = call["call_id"]
        if not isinstance(call_id, str) or call_id == "":
            fail("call_id must be a non-empty string")
        if call_id in seen_ids:
            fail("call_id values must be unique")
        seen_ids.add(call_id)

        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        if not is_number(loss_without):
            fail("loss_without_call must be a finite number")
        if not is_number(loss_with):
            fail("loss_with_call must be a finite number")

        prediction_tokens = call["prediction_tokens"]
        if not isinstance(prediction_tokens, int) or isinstance(prediction_tokens, bool):
            fail("prediction_tokens must be an integer")
        if prediction_tokens < 0:
            fail("prediction_tokens must be non-negative")

        parseable = call["parseable"]
        if not isinstance(parseable, bool):
            fail("parseable must be a boolean")

        raw_gain = loss_without - loss_with
        normalized_weight = 1.0 / max(1, prediction_tokens)
        normalized_gain = raw_gain * normalized_weight
        accepted = parseable and normalized_gain >= threshold

        if accepted:
            accepted_call_ids.append(call_id)

        diagnostics.append({
            "source_index": source_index,
            "call_id": call_id,
            "parseable": parseable,
            "prediction_tokens": prediction_tokens,
            "normalized_weight": round(normalized_weight, 6),
            "loss_without_call": round(loss_without, 6),
            "loss_with_call": round(loss_with, 6),
            "weighted_loss_without_call": round(loss_without * normalized_weight, 6),
            "weighted_loss_with_call": round(loss_with * normalized_weight, 6),
            "gain": round(raw_gain, 6),
            "normalized_gain": round(normalized_gain, 6),
            "accepted": accepted,
        })

    accepted_count = sum(1 for item in diagnostics if item["accepted"])
    total_normalized_gain = sum(item["normalized_gain"] for item in diagnostics if item["accepted"])

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
        "accepted_count": accepted_count,
        "total_accepted_normalized_gain": round(total_normalized_gain, 6),
    }
"}
